use crate::aap::caps::http_client;
use crate::wasi::clocks::wall_clock;

struct Node;

/// Percent-encode a string for use as a URL query value (RFC 3986 unreserved set kept).
fn encode_query(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

/// Convert seconds since the Unix epoch to a `YYYY-MM-DD` UTC date string.
/// Uses Howard Hinnant's `civil_from_days` algorithm.
fn civil_date(secs: u64) -> String {
    let days = (secs / 86_400) as i64;
    let z = days + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let y = if m <= 2 { y + 1 } else { y };
    format!("{:04}-{:02}-{:02}", y, m, d)
}

impl Guest for Node {
    fn run(tick: Tick) -> RunInfo {
        // Read the clock first so enrichment latency does not affect `started`.
        let now = wall_clock::now();
        let started: u64 = now.seconds;
        let date = civil_date(started);

        // Enrichment lookup for this input. The result is deliberately discarded:
        // the node's output does not depend on the enrichment record, and a
        // transport failure (returned as Err) must not fail the run.
        // Out-of-allowlist requests trap at the boundary, per the http-client contract.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            encode_query(&tick.reason)
        );
        let _ = http_client::fetch(&url);

        RunInfo { date, started }
    }
}

export!(Node);
